package com.example.registration.controller;

import com.example.registration.dto.UserRegistrationDto;
import com.example.registration.model.User;
import com.example.registration.repository.UserRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.crypto.bcrypt.BCrypt;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.*;

import javax.validation.Valid;

@Controller
public class RegistrationController {

  private final UserRepository userRepository;

  @Autowired
  public RegistrationController(UserRepository userRepository) {
    this.userRepository = userRepository;
  }

  @GetMapping("/register")
  public String showRegistrationForm(Model model) {
    model.addAttribute("user", new UserRegistrationDto());
    return "register";
  }

  @PostMapping("/register")
  public String processRegistration(@ModelAttribute("user") @Valid UserRegistrationDto dto,
                                    BindingResult bindingResult,
                                    Model model) {
    if (bindingResult.hasErrors()) {
      return "register";
    }

    if (userRepository.findByEmail(dto.getEmail()).isPresent()) {
      bindingResult.rejectValue("email", "error.user", "An account already exists for this email.");
      return "register";
    }

    // Hash the password with BCrypt
    String hashed = BCrypt.hashpw(dto.getPassword(), BCrypt.gensalt(12));
    User user = new User(dto.getName(), dto.getEmail(), hashed);
    userRepository.save(user);

    model.addAttribute("name", user.getName());
    return "register_success";
  }
}
```
Note: I used BCrypt.hashpw directly from spring-security-crypto. Alternatively you can use BCryptPasswordEncoder.

