Below is a complete Object Pascal (Delphi/Free Pascal-compatible) program that implements the described solution. It reads from standard input:

- First line: the binary string s
- Second line: an integer m = number of queries
- Next m lines: two integers per line, firsti and secondi

For each query the program prints a line with the answer "left right" or "-1 -1" when no substring matches.

Algorithm summary:
- For each start index i in s:
  - If s[i] = '0' we only consider the single-character substring "0" (value 0) because any longer substring starting with '0' will be longer and thus not optimal for value 0.
  - If s[i] = '1' we build substring values by scanning at most 31 bits (since 2^30 > 10^9) and compute their integer values progressively using bit shifts.
- We maintain a dictionary mapping value -> the best [left,right] substring (shortest length, and if equal lengths, smallest left).
- For each query compute target = first xor second and look up the mapping.

Code:

```pascal
program SubstringXorQueries;

{$mode objfpc}{$H+}

uses
  SysUtils, Generics.Collections, Math;

type
  TPair = record
    L, R: Integer;
  end;

var
  s: string;
  m, i, j: Integer;
  queriesFirst, queriesSecond: array of Integer;
  dict: TDictionary<Integer, TPair>;
  n: Integer;

function MinInt(a, b: Integer): Integer;
begin
  if a < b then Result := a else Result := b;
end;

procedure AddOrUpdate(var D: TDictionary<Integer, TPair>; key: Integer; leftIdx, rightIdx: Integer);
var
  existing: TPair;
  lenNew, lenOld: Integer;
begin
  lenNew := rightIdx - leftIdx + 1;
  if D.TryGetValue(key, existing) then
  begin
    lenOld := existing.R - existing.L + 1;
    if (lenNew < lenOld) or ((lenNew = lenOld) and (leftIdx < existing.L)) then
    begin
      existing.L := leftIdx;
      existing.R := rightIdx;
      D.AddOrSetValue(key, existing);
    end;
  end
  else
  begin
    existing.L := leftIdx;
    existing.R := rightIdx;
    D.Add(key, existing);
  end;
end;

function SplitToInts(const line: string): TArray<Integer>;
var
  parts: TStringArray;
  sline: string;
  k: Integer;
begin
  sline := Trim(line);
  if sline = '' then
  begin
    SetLength(Result, 0);
    Exit;
  end;
  parts := sline.Split([' ', #9], TStringSplitOptions.ExcludeEmpty);
  SetLength(Result, Length(parts));
  for k := 0 to High(parts) do
    Result[k] := StrToInt(parts[k]);
end;

begin
  try
    // Read binary string s
    if not Eof then
    begin
      ReadLn(s);
      s := Trim(s);
    end
    else
      Exit;

    // Read number of queries m
    if Eof then Exit;
    ReadLn(m);
    if m < 0 then m := 0;
    SetLength(queriesFirst, m);
    SetLength(queriesSecond, m);

    // Read m queries
    for i := 0 to m - 1 do
    begin
      if Eof then
      begin
        // No more input; break
        queriesFirst[i] := 0;
        queriesSecond[i] := 0;
      end
      else
      begin
        var line: string;
        ReadLn(line);
        var arr := SplitToInts(line);
        if Length(arr) >= 2 then
        begin
          queriesFirst[i] := arr[0];
          queriesSecond[i] := arr[1];
        end
        else if Length(arr) = 1 then
        begin
          queriesFirst[i] := arr[0];
          queriesSecond[i] := 0;
        end
        else
        begin
          queriesFirst[i] := 0;
          queriesSecond[i] := 0;
        end;
      end;
    end;

    n := Length(s);
    dict := TDictionary<Integer, TPair>.Create;
    try
      // Build dictionary of all feasible substring values
      for i := 1 to n do
      begin
        if s[i] = '0' then
        begin
          // only consider single '0' substring at position i-1
          AddOrUpdate(dict, 0, i - 1, i - 1);
          // skip longer substrings starting with '0' because they are longer and won't be optimal
        end
        else
        begin
          // s[i] = '1' -> build values up to 31 bits
          var value: Integer := 0;
          var limit := MinInt(n, i + 30); // 31 bits max
          for j := i to limit do
          begin
            // shift left and add current bit
            value := (value shl 1) + (Ord(s[j]) - Ord('0'));
            AddOrUpdate(dict, value, i - 1, j - 1);
          end;
        end;
      end;

      // Answer queries
      for i := 0 to m - 1 do
      begin
        var target := queriesFirst[i] xor queriesSecond[i];
        var ansPair: TPair;
        if dict.TryGetValue(target, ansPair) then
          WriteLn(ansPair.L, ' ', ansPair.R)
        else
          WriteLn('-1 -1');
      end;
    finally
      dict.Free;
    end;
  except
    on E: Exception do
      Writeln('Error: ', E.Message);
  end;
end.
```

Notes:
- The program restricts substring length to at most 31 bits when the substring starts with '1' because the constraints on queries (<= 10^9) mean values requiring more bits can't be necessary.
- For characters '0' we only register the one-character substring since longer ones starting with '0' are strictly longer and won't be optimal (they represent the same value 0 but are longer).
- The dictionary stores the best substring found for each numeric value according to the problem criteria (shortest length, then smallest left index).

